"use client";

//
// Share formats generated by the SERVER (desktop FormDetailSlideover Share
// tab): hosted page / iframe / script / React. Each reads
// GET /api/v1/forms/{id}/embed/{flavor}, which bakes in the deployment's
// canonical forms host — the one contract that knows where embed.js and the
// hosted renderer actually live. The snippet is rendered verbatim and copied
// verbatim; nothing is rebuilt client-side.
//
// The route is admin-scoped, and it answers 503 when the deployment has no
// public forms host configured. Both render as the reason, never a blank box.

import { useId, useState } from "react";
import { ExternalLink } from "lucide-react";
import { useQuery } from "@tanstack/react-query";

import { CopyTextButton } from "@/components/copy-text-button";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { apiErrorMessage } from "@/lib/api";
import { effectiveAuthRole, type MeResponse } from "@/lib/auth-api";
import { canAdminForms } from "@/lib/forms-authority";
import {
  FORM_SHARE_TABS,
  embedFlavorForTab,
  getFormEmbedSnippet,
  shareTextForTab,
  type FormShareTab,
} from "@/lib/forms-extras-api";
import { base, STALE } from "@/lib/query-keys";
import { cn } from "@/lib/utils";

export const EMBED_ADMIN_REQUIRED_MESSAGE =
  "Owner or admin access is required to retrieve the server-generated share and embed code.";

interface EmbedFlavorPickerProps {
  formId: string;
  identity: MeResponse | null | undefined;
}

export function EmbedFlavorPicker({ formId, identity }: EmbedFlavorPickerProps) {
  const ids = useId();
  const [tab, setTab] = useState<FormShareTab>("hosted");
  const flavor = embedFlavorForTab(tab);
  const canAdmin = canAdminForms(identity);
  const tenantId = identity?.tenant_id ?? "anon";
  const role = identity ? effectiveAuthRole(identity) : null;

  const embedQuery = useQuery({
    queryKey: [...base("forms", tenantId, role), "embed", formId, flavor] as const,
    queryFn: () => getFormEmbedSnippet(formId, flavor),
    enabled: canAdmin,
    staleTime: STALE.detail,
    retry: false,
  });

  const embed = canAdmin ? (embedQuery.data ?? null) : null;
  const text = embed ? shareTextForTab(tab, embed) : "";
  const label = FORM_SHARE_TABS.find((t) => t.value === tab)?.label ?? tab;
  const descriptionId = `${ids}-desc`;

  return (
    <section className="min-w-0 space-y-3" aria-labelledby={`${ids}-title`}>
      <div>
        <h2 id={`${ids}-title`} className="text-sm font-semibold">
          Share &amp; embed code
        </h2>
        <p id={descriptionId} className="mt-1 text-xs text-muted-foreground">
          Generated by the server from this workspace&apos;s configured public
          forms host.
        </p>
      </div>

      <div
        role="group"
        aria-label="Share format"
        className="inline-flex flex-wrap overflow-hidden rounded-md border"
      >
        {FORM_SHARE_TABS.map((t) => (
          <button
            key={t.value}
            type="button"
            aria-pressed={tab === t.value}
            disabled={!canAdmin}
            onClick={() => setTab(t.value)}
            className={cn(
              "min-h-9 px-3 py-1 text-xs disabled:cursor-not-allowed disabled:opacity-50",
              tab === t.value
                ? "bg-primary text-primary-foreground"
                : "bg-background text-muted-foreground hover:text-foreground",
            )}
          >
            {t.label}
          </button>
        ))}
      </div>

      {!canAdmin ? (
        <p role="note" className="text-xs text-muted-foreground">
          {EMBED_ADMIN_REQUIRED_MESSAGE}
        </p>
      ) : embedQuery.isPending ? (
        <p role="status" className="text-xs text-muted-foreground">
          Loading the server-generated {label.toLowerCase()} code…
        </p>
      ) : embedQuery.isError ? (
        <div role="alert" className="space-y-2 text-xs text-destructive">
          <p>
            {apiErrorMessage(
              embedQuery.error,
              "Could not load the server-generated share code.",
            )}{" "}
            Copying stays disabled until the server confirms the canonical URL.
          </p>
          <Button
            type="button"
            size="sm"
            variant="outline"
            onClick={() => void embedQuery.refetch()}
          >
            Retry
          </Button>
        </div>
      ) : embed ? (
        <div className="min-w-0 space-y-2">
          <pre
            tabIndex={0}
            role="group"
            aria-label={`${label} share code`}
            aria-describedby={descriptionId}
            className="max-w-full overflow-x-auto whitespace-pre rounded-md bg-muted p-4 text-xs focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            {text}
          </pre>
          <p className="text-xs text-muted-foreground">
            <Badge variant="secondary">
              {tab === "hosted" ? "URL" : embed.language}
            </Badge>{" "}
            {tab === "hosted"
              ? "Share this link directly or open it to check the live page."
              : embed.instructions}{" "}
            Served by {embed.publicHost}.
          </p>
          <div className="flex flex-wrap items-center gap-2">
            <CopyTextButton
              value={text}
              label={tab === "hosted" ? "Copy hosted link" : "Copy code"}
            />
            {tab === "hosted" ? (
              <a
                href={embed.publicUrl}
                target="_blank"
                rel="noopener noreferrer"
                className="inline-flex min-h-9 items-center gap-1 text-xs text-muted-foreground hover:text-foreground"
              >
                Open hosted page
                <ExternalLink className="h-3.5 w-3.5" aria-hidden />
              </a>
            ) : null}
          </div>
        </div>
      ) : null}
    </section>
  );
}
